import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Step of {@code POST /api/owners}: when the request opts in with {@code sharesHousehold: true},
 * assigns a stable shared {@code householdId} to the new owner and to every existing owner sharing
 * its household (same last name and address, compared case-insensitively with collapsed
 * whitespace — the same comparison {@link RequireUniqueIdentity} folds into the identity key).
 *
 * <p>The identifier is derived deterministically from the normalised last name and address, so all
 * members of a household resolve to the same value regardless of creation order, and the existing
 * members are updated in place so they carry it too. A request that does not set the flag is left
 * untouched (no household). Runs after {@link BuildOwner}, under the write transaction.
 */
public class AssignHouseholdId {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        String householdId = deriveHouseholdId(lastName, address);
        owner.setHouseholdId(householdId);
        for (Owner existing : ownerRepository.findAll()) {
